class Solution {
  private static final int MOD = 1_000_000_007;

  public int createSortedArray(int[] instructions) {
    int maximum = 100000;
    Fenwick tree = new Fenwick(maximum + 1);
    long cost = 0;
    int inserted = 0;
    for (int value : instructions) {
      int less = tree.query(value - 1);
      int greater = inserted - tree.query(value);
      cost = (cost + Math.min(less, greater)) % MOD;
      tree.add(value, 1);
      inserted++;
    }
    return (int) cost;
  }

  private static class Fenwick {
    private final int[] tree;

    Fenwick(int size) {
      tree = new int[size + 1];
    }

    void add(int index, int amount) {
      for (; index < tree.length; index += index & -index) tree[index] += amount;
    }

    int query(int index) {
      int sum = 0;
      for (; index > 0; index -= index & -index) sum += tree[index];
      return sum;
    }
  }
}
